code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0,r1 = min(r for r,c in cells), max(r for r,c in cells)
    c0,c1 = min(c for r,c in cells), max(c for r,c in cells)
    markers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,2)]
    def paint(r,c):
        if out[r][c] == 0: out[r][c] = 2
    # The solid rectangle projects toward each horizontal edge; side markers cast a short shadow.
    for r in range(r0,r1+1):
        left = [c for rr,c in markers if rr == r and c < c0]
        right = [c for rr,c in markers if rr == r and c > c1]
        if not left and not right:
            go_left = go_right = True
        elif left and not right:
            go_right = c0 - max(left) <= 5
            go_left = False
        elif right and not left:
            go_left = min(right) - c1 <= 5
            go_right = False
        else:
            go_left = go_right = False
        if go_left:
            for c in range(0,c0): paint(r,c)
        if go_right:
            for c in range(c1+1,w): paint(r,c)
    # Markers on a vertical ray block that ray; unblocked rectangle columns project to the edge.
    for c in range(c0,c1+1):
        up_block = any(cc == c and r < r0 for r,cc in markers)
        down_block = any(cc == c and r > r1 for r,cc in markers)
        if not up_block:
            for r in range(r0): paint(r,c)
        if not down_block:
            for r in range(r1+1,h): paint(r,c)
    return out
'''
